function C.wrap(s, name, maxw, maxlines)
  local out = {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local w = word
      while C.tw(name, w) > maxw do
        local cut = #w
        while cut > 1 and C.tw(name, w:sub(1, cut)) > maxw do cut = cut - 1 end
        if line ~= '' then out[#out + 1] = line; line = '' end
        out[#out + 1] = w:sub(1, cut)
        w = w:sub(cut + 1)
        if w == '' then break end
      end
      if w ~= '' then
        local cand = line == '' and w or (line .. ' ' .. w)
        if line ~= '' and C.tw(name, cand) > maxw then out[#out + 1] = line; line = w else line = cand end
      end
    end
    out[#out + 1] = line
  end
  if maxlines and #out > maxlines then
    local last = out[maxlines]
    while #last > 1 and C.tw(name, last .. '...') > maxw do last = last:sub(1, -2) end
    local cut = {}
    for i = 1, maxlines - 1 do cut[i] = out[i] end
    cut[maxlines] = last .. '...'
    out = cut
  end
