-- JSON (strict enough for our own files; non-ASCII escapes become '?')
function C.json_decode(s)
  local pos = 1
  local ESC = { ['"'] = '"', ['\\'] = '\\', ['/'] = '/', b = '\b', f = '\f', n = '\n', r = '\r', t = '\t' }
  local function ws() pos = s:find('[^ \t\r\n]', pos) or (#s + 1) end
  local parse
  local function str()
    local buf, i = {}, pos + 1
    while true do
      local j = s:find('["\\]', i)
      if not j then error('unterminated string') end
      buf[#buf + 1] = s:sub(i, j - 1)
      if s:sub(j, j) == '"' then pos = j + 1; return table.concat(buf) end
      local e = s:sub(j + 1, j + 1)
      if ESC[e] then buf[#buf + 1] = ESC[e]; i = j + 2
      elseif e == 'u' then
        local cp = tonumber(s:sub(j + 2, j + 5), 16)
        buf[#buf + 1] = (cp and cp < 128) and string.char(cp) or '?'
        i = j + 6
      else error('bad escape') end
    end
  end
  function parse()
    ws()
    local c = s:sub(pos, pos)
    if c == '{' then
      local t = {}
      pos = pos + 1; ws()
      if s:sub(pos, pos) == '}' then pos = pos + 1; return t end
      while true do
        ws()
        if s:sub(pos, pos) ~= '"' then error('key expected') end
        local k = str()
        ws()
        if s:sub(pos, pos) ~= ':' then error('colon expected') end
        pos = pos + 1
        t[k] = parse()
        ws()
        local d = s:sub(pos, pos); pos = pos + 1
        if d == '}' then return t end
        if d ~= ',' then error('comma expected') end
      end
    elseif c == '[' then
      local t = {}
      pos = pos + 1; ws()
      if s:sub(pos, pos) == ']' then pos = pos + 1; return t end
      while true do
        t[#t + 1] = parse()
        ws()
        local d = s:sub(pos, pos); pos = pos + 1
        if d == ']' then return t end
        if d ~= ',' then error('comma expected') end
      end
    elseif c == '"' then return str()
    elseif s:sub(pos, pos + 3) == 'true' then pos = pos + 4; return true
    elseif s:sub(pos, pos + 4) == 'false' then pos = pos + 5; return false
    elseif s:sub(pos, pos + 3) == 'null' then pos = pos + 4; return nil
    else
      local num = s:match('^-?%d+%.?%d*[eE]?[+-]?%d*', pos)
      if not num or num == '' then error('unexpected character at ' .. pos) end
      pos = pos + #num
      return tonumber(num)
    end
  end
  return parse()
end
function C.decode(body)
  local ok, v = pcall(C.json_decode, body)
  if ok and type(v) == 'table' then return v end
  return nil
end

-- dates ----------------------------------------------------------------------------
function C.clock()
  local ok, t = pcall(function() return ctx.clock:now() end)
  return (ok and type(t) == 'table') and t or {}
end
function C.now_ms()
  local ok, t = pcall(function() return ctx.clock:millis() end)
  return ok and tonumber(t) or 0
end
function C.now_sec() return math.floor(tonumber(C.clock().epoch_sec) or 0) end
-- days since 1970-01-01 -> year, month, day (civil calendar; small numbers only)
function C.civil(z)
  z = z + 719468
  local era = z // 146097
  local doe = z - era * 146097
  local yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
  local y = yoe + era * 400
  local doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
  local mp = (5 * doy + 2) // 153
  local d = doy - (153 * mp + 2) // 5 + 1
  local m = mp < 10 and mp + 3 or mp - 9
  if m <= 2 then y = y + 1 end
  return y, m, d
end
-- today's date by the wall clock, 'YYYY-MM-DD' (nil when the clock is not set)
function C.local_date()
  local t = C.clock()
  if tonumber(t.year) and tonumber(t.month) and tonumber(t.day) and t.year > 2000 then
    return string.format('%04d-%02d-%02d', t.year, t.month, t.day)
  end
  local epoch = tonumber(t.epoch_sec)
  if not epoch or epoch < 1700000000 then return nil end
  local wall = tonumber(t.hour) and (t.hour * 3600 + (t.minute or 0) * 60 + (t.second or 0)) or nil
  local off = 0
  if wall then
    off = (wall - epoch % 86400) % 86400
    if off > 14 * 3600 then off = off - 86400 end
    off = math.floor(off / 900 + 0.5) * 900
  end
  local y, m, d = C.civil((math.floor(epoch) + off) // 86400)
  return string.format('%04d-%02d-%02d', y, m, d)
end
C.MONTHS = { 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec' }
function C.pretty(d, weekday)
  local y, m, dd = tostring(d):match('^(%d+)%-(%d+)%-(%d+)$')
  if not y then return tostring(d) end
  local mo = C.MONTHS[tonumber(m)] or m
  return (weekday and weekday ~= '' and (weekday:sub(1, 3) .. ', ') or '') .. mo .. ' ' .. tonumber(dd) .. ', ' .. y
end

